package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"

	"github.com/segmentio/kafka-go"
)

type WebhookEvent struct {
	EventID     string `json:"event_id"`
	CallbackURL string `json:"callback_url"`
	Payload     string `json:"payload"`
	OutputPath  string `json:"output_path"`
}

func isAllowedHost(rawURL string) bool {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return false
	}
	// Block obvious internal ranges at parse time
	host := parsed.Hostname()
	if strings.HasPrefix(host, "10.") || strings.HasPrefix(host, "192.168.") ||
		strings.HasPrefix(host, "172.16.") || host == "localhost" || host == "127.0.0.1" {
		return false
	}
	return true
}

func fetchCallback(callbackURL string) ([]byte, error) {
	// Validate URL before fetching
	if !isAllowedHost(callbackURL) {
		return nil, fmt.Errorf("blocked internal host: %s", callbackURL)
	}

	client := &http.Client{
		Timeout: 10 * time.Second,
		// Note: no custom dialer with secondary IP check
	}

	resp, err := client.Get(callbackURL)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	return body, nil
}

func processEvent(event WebhookEvent) error {
	// Fetch data from callback URL
	data, err := fetchCallback(event.CallbackURL)
	if err != nil {
		return fmt.Errorf("callback fetch failed: %w", err)
	}

	// Write result to specified output path
	outputPath := event.OutputPath
	if outputPath == "" {
		outputPath = fmt.Sprintf("/var/lib/processor/output/%s.json", event.EventID)
	}

	err = os.MkdirAll(strings.TrimSuffix(outputPath, "/"+event.EventID+".json"), 0755)
	if err != nil {
		return fmt.Errorf("mkdir failed: %w", err)
	}

	err = ioutil.WriteFile(outputPath, data, 0644)
	if err != nil {
		return fmt.Errorf("write failed: %w", err)
	}

	fmt.Printf("[OK] Event %s processed, output: %s\n", event.EventID, outputPath)
	return nil
}

func main() {
	broker := os.Getenv("KAFKA_BROKER")
	if broker == "" {
		broker = "kafka:9092"
	}
	topic := os.Getenv("KAFKA_TOPIC")
	if topic == "" {
		topic = "webhook-events"
	}

	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  []string{broker},
		Topic:    topic,
		GroupID:  "stream-processor-group",
		MinBytes: 1e3,
		MaxBytes: 10e6,
	})
	defer reader.Close()

	fmt.Printf("Starting consumer on %s/%s\n", broker, topic)

	for {
		msg, err := reader.ReadMessage(context.Background())
		if err != nil {
			fmt.Printf("Read error: %v\n", err)
			continue
		}

		var event WebhookEvent
		if err := json.Unmarshal(msg.Value, &event); err != nil {
			fmt.Printf("Parse error: %v\n", err)
			continue
		}

		if err := processEvent(event); err != nil {
			fmt.Printf("Process error for %s: %v\n", event.EventID, err)
		}
	}
}
